package com.supersports.support;
import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;
@Repository class SupportRepository{
 private final JdbcTemplate jdbc;SupportRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Transactional Map<String,Object> create(UUID id,String owner,UUID order,String title,String body,UUID op){String cleanTitle=SupportRules.text(title,160),cleanBody=SupportRules.text(body,4000),hash=SupportRules.hash(cleanBody);jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",ps->ps.setString(1,"support-create:"+op),rs->{rs.next();return null;});var prior=jdbc.queryForList("SELECT t.id,t.customer_subject,t.order_id,t.subject,m.request_hash FROM support_message m JOIN support_ticket t ON t.id=m.ticket_id WHERE m.operation_id=?",op);if(!prior.isEmpty()){var old=prior.getFirst();if(!owner.equals(old.get("customer_subject"))||!Objects.equals(order,old.get("order_id"))||!cleanTitle.equals(old.get("subject"))||!hash.equals(old.get("request_hash").toString().trim()))throw new IllegalStateException("Ticket operation conflicts");return Map.of("ticketId",old.get("id"),"status","OPEN","replayed",true);}jdbc.update("INSERT INTO support_ticket(id,customer_subject,order_id,subject) VALUES (?,?,?,?)",id,owner,order,cleanTitle);jdbc.update("INSERT INTO support_message(id,ticket_id,operation_id,actor_subject,audience,body,request_hash) VALUES (?,?,?,?,?,?,?)",UUID.randomUUID(),id,op,owner,"CUSTOMER",cleanBody,hash);return Map.of("ticketId",id,"status","OPEN","replayed",false);}
 List<Map<String,Object>> mine(String owner){return jdbc.queryForList("SELECT id AS \"ticketId\",order_id AS \"orderId\",subject,status,revision,created_at AS \"createdAt\",updated_at AS \"updatedAt\" FROM support_ticket WHERE customer_subject=? ORDER BY updated_at DESC",owner);}
 Map<String,Object> detail(UUID id,String owner,boolean operator){String sql="SELECT id AS \"ticketId\",customer_subject AS \"customerSubject\",order_id AS \"orderId\",subject,status,revision,created_at AS \"createdAt\",updated_at AS \"updatedAt\" FROM support_ticket WHERE id=?"+(operator?"":" AND customer_subject=?");var rows=operator?jdbc.queryForList(sql,id):jdbc.queryForList(sql,id,owner);if(rows.isEmpty())return null;var result=new LinkedHashMap<String,Object>(rows.getFirst());result.put("messages",jdbc.queryForList("SELECT id,actor_subject AS \"actorSubject\",audience,body,created_at AS \"createdAt\" FROM support_message WHERE ticket_id=? ORDER BY created_at,id",id));return result;}
 List<Map<String,Object>> queue(){return jdbc.queryForList("SELECT id AS \"ticketId\",customer_subject AS \"customerSubject\",order_id AS \"orderId\",subject,status,revision,updated_at AS \"updatedAt\" FROM support_ticket WHERE status<>'RESOLVED' ORDER BY updated_at,id LIMIT 200");}
 @Transactional Map<String,Object> message(UUID ticket,String owner,boolean operator,String actor,String body,UUID op){String clean=SupportRules.text(body,4000),hash=SupportRules.hash(clean);jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",ps->ps.setString(1,"support-message:"+op),rs->{rs.next();return null;});var old=jdbc.queryForList("SELECT ticket_id,actor_subject,body,request_hash FROM support_message WHERE operation_id=?",op);if(!old.isEmpty()){var row=old.getFirst();if(!ticket.equals(row.get("ticket_id"))||!actor.equals(row.get("actor_subject"))||!hash.equals(row.get("request_hash").toString().trim()))throw new IllegalStateException("Message operation conflicts");return Map.of("ticketId",ticket,"replayed",true);}var tickets=jdbc.queryForList("SELECT customer_subject,status FROM support_ticket WHERE id=? FOR UPDATE",ticket);if(tickets.isEmpty()||(!operator&&!owner.equals(tickets.getFirst().get("customer_subject"))))throw new NoSuchElementException();String status=tickets.getFirst().get("status").toString();if(!operator&&status.equals("RESOLVED")){jdbc.update("UPDATE support_ticket SET status='OPEN',revision=revision+1,updated_at=now() WHERE id=?",ticket);jdbc.update("INSERT INTO support_audit(id,ticket_id,actor_subject,previous_status,next_status,reason) VALUES (?,?,?,?,?,?)",UUID.randomUUID(),ticket,actor,status,"OPEN","Customer replied to resolved ticket");}jdbc.update("INSERT INTO support_message(id,ticket_id,operation_id,actor_subject,audience,body,request_hash) VALUES (?,?,?,?,?,?,?)",UUID.randomUUID(),ticket,op,actor,operator?"OPERATOR":"CUSTOMER",clean,hash);jdbc.update("UPDATE support_ticket SET updated_at=now() WHERE id=?",ticket);return Map.of("ticketId",ticket,"replayed",false);}
 @Transactional Map<String,Object> transition(UUID ticket,String target,String actor,String reason){String clean=SupportRules.text(reason,500);var rows=jdbc.queryForList("SELECT status FROM support_ticket WHERE id=? FOR UPDATE",ticket);if(rows.isEmpty())throw new NoSuchElementException();String old=rows.getFirst().get("status").toString();if(!SupportRules.transition(old,target))throw new IllegalStateException("Invalid support status transition");jdbc.update("UPDATE support_ticket SET status=?,revision=revision+1,updated_at=now() WHERE id=?",target,ticket);jdbc.update("INSERT INTO support_audit(id,ticket_id,actor_subject,previous_status,next_status,reason) VALUES (?,?,?,?,?,?)",UUID.randomUUID(),ticket,actor,old,target,clean);return Map.of("ticketId",ticket,"status",target);}
}
